<?php require_once __DIR__.'/config/config.php'; $pageTitle='Auctions'; $bodyClass='reference-marketplace'; $auctions=db()->query("SELECT a.*, f.name flower_name FROM auctions a LEFT JOIN flowers f ON f.id=a.flower_id ORDER BY a.starts_at DESC")->fetchAll(); require __DIR__.'/includes/header.php'; ?>
<main class="page-wrap"><span class="eyebrow">THE AUCTION FLOOR</span><h1 class="page-title">Upcoming auctions</h1><p class="lead">Explore scheduled flower auctions and their current status.</p><div class="table-wrap"><table><thead><tr><th>Auction</th><th>Flower</th><th>Starts</th><th>Base price</th><th>Status</th></tr></thead><tbody><?php foreach($auctions as $a): ?><tr><td><?= e($a['title']) ?></td><td><?= e($a['flower_name']??'To be announced') ?></td><td><?= e(date('d M Y, h:i A',strtotime($a['starts_at']))) ?></td><td>₹<?= number_format((float)$a['base_price'],2) ?></td><td><span class="status"><?= e(ucfirst($a['status'])) ?></span></td></tr><?php endforeach; ?><?php if(!$auctions): ?><tr><td colspan="5">No auctions scheduled yet.</td></tr><?php endif; ?></tbody></table></div></main><?php require __DIR__.'/includes/footer.php'; ?>
